import { Injectable } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { CreateDimensionDto, DimensionTier, overageAllowedEnum } from './create-dimension.dto.js';

/**
 * The value used to represent an unbounded upper limit on a tier.
 */
export const UNBOUNDED_TIER_UPPER_BOUND = 'inf';

/**
 * The maximum amount of decimal places supported on any price field.
 */
export const MAX_PRICE_DECIMAL_PLACES = 8;

/**
 * Determines if the given value is a string which can safely be converted into a number.
 */
export const isNumericString = (value: unknown): boolean => {
    if (typeof value !== 'string') {
        return false;
    }
    if (value.trim() === '') {
        return false;
    }
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore Type coercion is intentional here, the value is a numeric string
    return !isNaN(value) && !isNaN(parseFloat(value));
};

const decimalPlaces = (value: string): number => value.split('.')[1]?.length ?? 0;

/**
 * Tiers are always processed in the order given by their `tierPosition`.
 * The position is a numeric string so it is sorted numerically and not lexicographically.
 */
export const sortTiersByPosition = <T extends { tierPosition?: string }>(tiers: T[]): T[] =>
    [...tiers].sort((first, second) => Number(first.tierPosition) - Number(second.tierPosition));

/**
 * Returns the tiers of a dimension sorted by their position, an empty array is returned for
 * dimensions which are not tiered.
 */
export const getSortedTiers = (dimension?: { tiers?: DimensionTier[] | null }): DimensionTier[] => {
    const tiers = dimension?.tiers;
    if (!Array.isArray(tiers) || !tiers.length) {
        return [];
    }
    return sortTiersByPosition(tiers);
};

/**
 * Validates the volume based pricing tiers of a dimension.
 *
 * The following rules are enforced:
 * - `tiers` must be a non empty array of tier objects.
 * - `tierPosition` must be a numeric string integer, and must be unique within the array.
 * - `upperBound` must be a positive numeric string or the string `"inf"`.
 * - `upperBound` values must increase, without overlapping, when the tiers are sorted by position.
 * - `upperBound` values must be a multiple of the `usageIncrement` of the dimension.
 * - Only the last tier may use `"inf"` as its `upperBound`.
 * - Every tier after the first one requires a `unitPrice`, an omitted `unitPrice` on the first tier
 *   represents a free tier.
 * - Tiered dimensions cannot be combined with `usageEntitlement`, `consumptionPrice` or
 *   `overageAllowed: true`.
 *
 * @returns an array of human readable validation errors, empty when the tiers are valid.
 */
export const validateDimensionTiers = ({
    tiers,
    usageIncrement,
    consumptionPrice,
    usageEntitlement,
    overageAllowed,
}: {
    tiers?: DimensionTier[] | null;
    usageIncrement?: string | number;
    consumptionPrice?: string;
    usageEntitlement?: number | 'inf';
    overageAllowed?: overageAllowedEnum | boolean;
}): string[] => {
    if (tiers === undefined || tiers === null) {
        return [];
    }
    if (!Array.isArray(tiers)) {
        return ['tiers must be an array of tier objects'];
    }
    if (!tiers.length) {
        return ['tiers must contain at least one tier'];
    }

    const errors: string[] = [];

    if (consumptionPrice !== undefined && consumptionPrice !== null) {
        errors.push(
            'tiers cannot be combined with consumptionPrice, the unitPrice of every tier defines the price of a tiered dimension',
        );
    }
    if (usageEntitlement !== undefined && usageEntitlement !== null) {
        errors.push('tiers cannot be combined with usageEntitlement');
    }
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore overageAllowed is a string enum, however booleans are defended against as well
    if (overageAllowed === overageAllowedEnum.true || overageAllowed === true) {
        errors.push('tiers cannot be combined with overageAllowed set to true');
    }

    const fieldErrors: string[] = [];
    tiers.forEach((tier, index) => {
        if (!tier || typeof tier !== 'object') {
            fieldErrors.push(`tiers[${index}] must be a tier object`);
            return;
        }
        const { tierPosition, upperBound, tierName, unitPrice } = tier;
        if (!isNumericString(tierPosition) || !Number.isInteger(Number(tierPosition)) || Number(tierPosition) < 0) {
            fieldErrors.push(
                `tiers[${index}].tierPosition: ${tierPosition} must be a numeric string representing a positive integer`,
            );
        }
        if (
            upperBound !== UNBOUNDED_TIER_UPPER_BOUND &&
            (!isNumericString(upperBound) || Number(upperBound) <= 0 || !Number.isFinite(Number(upperBound)))
        ) {
            fieldErrors.push(
                `tiers[${index}].upperBound: ${upperBound} must be a positive numeric string or the string "${UNBOUNDED_TIER_UPPER_BOUND}"`,
            );
        }
        if (tierName !== undefined && tierName !== null && (typeof tierName !== 'string' || tierName === '')) {
            fieldErrors.push(`tiers[${index}].tierName: ${tierName} must be a non empty string`);
        }
        if (unitPrice !== undefined && unitPrice !== null) {
            if (!isNumericString(unitPrice) || Number(unitPrice) < 0) {
                fieldErrors.push(
                    `tiers[${index}].unitPrice: ${unitPrice} must be a numeric string greater than or equal to 0`,
                );
            } else if (decimalPlaces(unitPrice) > MAX_PRICE_DECIMAL_PLACES) {
                fieldErrors.push(
                    `tiers[${index}].unitPrice: ${unitPrice} cannot have more than ${MAX_PRICE_DECIMAL_PLACES} digits of precision after the decimal place`,
                );
            }
        }
    });
    if (fieldErrors.length) {
        return [...errors, ...fieldErrors];
    }

    const sortedTiers = sortTiersByPosition(tiers);
    const positions = sortedTiers.map(({ tierPosition }) => Number(tierPosition));
    if (new Set(positions).size !== positions.length) {
        errors.push('tiers must have a unique tierPosition for every tier');
    }

    sortedTiers.forEach((tier, index) => {
        const isLastTier = index === sortedTiers.length - 1;
        const { upperBound, unitPrice, tierPosition } = tier;
        if (upperBound === UNBOUNDED_TIER_UPPER_BOUND && !isLastTier) {
            errors.push(
                `only the last tier can have an upperBound of "${UNBOUNDED_TIER_UPPER_BOUND}", tierPosition: ${tierPosition} does not`,
            );
        }
        if (index > 0 && (unitPrice === undefined || unitPrice === null)) {
            errors.push(
                `tiers[tierPosition: ${tierPosition}] requires a unitPrice, only the first tier may omit the unitPrice to represent a free tier`,
            );
        }
        if (index > 0) {
            const previousUpperBound = sortedTiers[index - 1].upperBound;
            if (
                previousUpperBound === UNBOUNDED_TIER_UPPER_BOUND ||
                (upperBound !== UNBOUNDED_TIER_UPPER_BOUND && Number(upperBound) <= Number(previousUpperBound))
            ) {
                errors.push(
                    `tier upperBound values must increase without overlapping, tierPosition: ${tierPosition} has an upperBound of ${upperBound} which does not come after ${previousUpperBound}`,
                );
            }
        }
        if (
            upperBound !== UNBOUNDED_TIER_UPPER_BOUND &&
            isNumericString(usageIncrement?.toString()) &&
            Number(usageIncrement) > 0 &&
            Number(upperBound) % Number(usageIncrement) !== 0
        ) {
            errors.push(
                `tier upperBound ${upperBound} must be a multiple of the usageIncrement ${usageIncrement} of the dimension`,
            );
        }
    });

    return errors;
};

@ValidatorConstraint({ name: 'ValidTiers', async: false })
@Injectable()
export class ValidTiersRule implements ValidatorConstraintInterface {
    validate(tiers: DimensionTier[], args: ValidationArguments) {
        const dimension = args?.object as CreateDimensionDto;
        return (
            validateDimensionTiers({
                tiers,
                usageIncrement: dimension?.usageIncrement,
                consumptionPrice: dimension?.consumptionPrice,
                usageEntitlement: dimension?.usageEntitlement,
                overageAllowed: dimension?.overageAllowed,
            }).length === 0
        );
    }

    defaultMessage(args: ValidationArguments) {
        const dimension = args?.object as CreateDimensionDto;
        return validateDimensionTiers({
            tiers: args?.value,
            usageIncrement: dimension?.usageIncrement,
            consumptionPrice: dimension?.consumptionPrice,
            usageEntitlement: dimension?.usageEntitlement,
            overageAllowed: dimension?.overageAllowed,
        }).join('. ');
    }
}

export function ValidTiers(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidTiers',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ValidTiersRule,
        });
    };
}

