/**
 * @author Paigo
 *
 * @Class
 * A single volume based pricing tier of a dimension.
 * Tiers allow high volume usage of a dimension to be billed with a different unit price.
 * <br><br>
 * All of the fields are strings so that no numerical precision is lost.
 */
export class DimensionTier {
    /**
     * The position of the tier within the tiers of the dimension.
     * Tiers are always evaluated in ascending numerical order of their position.
     * <br><br>
     * Example `"1"`
     */
    @IsString()
    @IsNotEmpty()
    @IsNumberString()
    @NumberStringIsInteger('tierPosition')
    @ApiProperty({
        name: 'tierPosition',
        description:
            'The position of the tier within the tiers of the dimension, tiers are evaluated in ascending numerical order.',
        example: '1',
        type: String,
        required: true,
    })
    public tierPosition: string;

    /**
     * The inclusive upper bound of usage covered by the tier.
     * The value is either a numeric string, or the string `"inf"` which may only be used on the
     * last tier and represents an unlimited upper bound.
     * <br><br>
     * Example `"1000"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
