        if (errors.length) {
            throw new BadRequestException(errors.join('. '));
        }
    }

    /**
     * Determines the tiers, and the pricing fields which are mutually exclusive with tiers,
     * of a dimension which is being updated.
     *
     * - When `tiers` is not part of the update the currently stored tiers are kept.
     * - When `tiers` is `null` the tiers of the dimension are removed.
     * - When `tiers` is an array it fully replaces the currently stored tiers.
     *
     * Since tiers are mutually exclusive with `consumptionPrice`, `usageEntitlement` and
     * `overageAllowed: true`, those fields are removed from a dimension which becomes tiered.
     * Explicitly setting one of them together with tiers in the same request is rejected.
     */
    public mergeTiersForUpdate({
        storedDimension,
        updatedFields,
    }: {
        storedDimension: ReadDimensionResponseData;
        updatedFields: Partial<UpdateDimensionDto>;
    }): {
        tiers?: DimensionTier[];
        consumptionPrice?: string;
        usageEntitlement?: number | 'inf';
        overageAllowed?: overageAllowedEnum;
    } {
        let tiers: DimensionTier[] | undefined;
        if (updatedFields?.tiers === null) {
            // Tiers are explicitly cleared out of the dimension
            tiers = undefined;
        } else if (updatedFields?.tiers !== undefined) {
            // Tiers are replaced with the tiers of the update
            tiers = updatedFields.tiers;
        } else {
            tiers = storedDimension?.tiers?.length ? storedDimension.tiers : undefined;
        }

        if (!tiers?.length) {
            return { tiers: undefined };
        }

        if (updatedFields?.consumptionPrice !== undefined && updatedFields?.consumptionPrice !== null) {
            throw new BadRequestException(
                'tiers cannot be combined with consumptionPrice, the unitPrice of every tier defines the price of a tiered dimension',
            );
        }
        if (updatedFields?.usageEntitlement !== undefined && updatedFields?.usageEntitlement !== null) {
            throw new BadRequestException('tiers cannot be combined with usageEntitlement');
        }
        if (updatedFields?.overageAllowed === overageAllowedEnum.true) {
            throw new BadRequestException('tiers cannot be combined with overageAllowed set to true');
        }

        const usageIncrement =
            updatedFields?.usageIncrement !== undefined && updatedFields?.usageIncrement !== null
                ? updatedFields.usageIncrement
                : storedDimension?.usageIncrement;

        this.validateTiers({ tiers, usageIncrement });

        return {
            tiers,
            // The pricing fields which are mutually exclusive with tiers are removed from the dimension
            consumptionPrice: undefined,
            usageEntitlement: undefined,
            overageAllowed: overageAllowedEnum.false,
        };
    }
}
