/**
 * Allocates the total usage of a dimension across the volume based pricing tiers of the dimension.
 *
 * Tiers are processed in ascending numerical order of their `tierPosition` and the `upperBound`
 * of every tier is inclusive, meaning a tier with an `upperBound` of `"1000"` which follows a
 * tier with an `upperBound` of `"100"` covers the usage between 101 and 1000.
 *
 * Only the tiers which have actually been consumed are returned.
 */
public static allocateUsageAcrossTiers({
    totalUsage,
    tiers,
}: {
    totalUsage: number;
    tiers: DimensionTier[];
}): { tier: DimensionTier; usage: number }[] {
    const sortedTiers = sortTiersByPosition(tiers ?? []);
    const usage = Number(totalUsage);
    if (!sortedTiers.length || !Number.isFinite(usage) || usage <= 0) {
        return [];
    }
    const allocations: { tier: DimensionTier; usage: number }[] = [];
    let lowerBound = 0;
    for (const tier of sortedTiers) {
        if (usage <= lowerBound) {
            break;
        }
        const upperBound =
            tier?.upperBound === UNBOUNDED_TIER_UPPER_BOUND ? Number.POSITIVE_INFINITY : Number(tier?.upperBound);
        if (!(upperBound > lowerBound)) {
            // Defends against malformed tiers, a bound which does not move forward consumes nothing
            continue;
        }
        const usageInTier = Math.min(usage, upperBound) - lowerBound;
        if (usageInTier > 0) {
            allocations.push({ tier, usage: usageInTier });
        }
        lowerBound = upperBound;
    }
    return allocations;
}

