/**
 * Determines if a price, which is stored as a string to preserve its precision, can be used to
 * charge a customer.
 */
static hasUsablePrice(price?: string): boolean {
    if (price === undefined || price === null || price === '') {
        return false;
    }
    return !isNaN(parseFloat(price)) && Number.isFinite(Number(price));
}

/**
 * Converts a price, stored as a string to preserve its precision, into the currency of the
 * invoice without losing any of the precision of the original price.
 */
static convertPriceForCurrency(price: string | undefined, exchangeRate = 1): number {
    if (!Offering.hasUsablePrice(price)) {
        // A missing price represents free usage, this happens on the first tier of a tiered dimension
        return 0;
    }
    const parsedPrice = parseFloat(price);
    return Number(
        (parsedPrice * exchangeRate).toFixed(
            Offering.getDecimalsForNumber(parsedPrice) === 0 ? 2 : Offering.getDecimalsForNumber(parsedPrice),
        ),
    );
}

/**
 * Generates one invoice line item for every volume based pricing tier which has been consumed
 * by the usage of the given dimension.
 *
 * The usage is allocated across the inclusive bounds of the tiers, every quantity is divided by
 * the usage increment of the dimension, and every tier is charged with its own unit price.
 */
static addTieredLineItemsForDimension({
    dimension,
    totalUsage,
    exchangeRate,
    lineItems,
    negative,
    offeringInstance,
}: {
    dimension: ReadDimensionResponseData;
    totalUsage: number;
    exchangeRate: number;
    lineItems: InvoiceLineItems;
    negative?: boolean;
    offeringInstance: Offering;
}): InvoiceLineItems {
    const tiers = getSortedTiers(dimension);
    if (!tiers.length) {
        return lineItems;
    }
    const {
        dimensionId,
        dimensionName,
        usageIncrement,
        consumptionUnit: { unit, type },
    } = dimension;
    const allocations = Billing.allocateUsageAcrossTiers({ totalUsage, tiers });
    allocations.forEach(({ tier, usage: usageInTier }) => {
        const unitCost = Offering.convertPriceForCurrency(tier?.unitPrice, exchangeRate);
        const shouldDisplayLineItem = Billing.determineIfLineItemShown({
            Offering: offeringInstance,
            dimension,
            totalUsage: usageInTier,
            unitCost,
            freeDimensionOnInvoice: offeringInstance?.settings?.freeDimensionOnInvoice,
        });
        if (!shouldDisplayLineItem) {
            return;
        }
        const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
            total: usageInTier,
            dimensionType: type,
            dimensionId,
            dimensionName,
            offeringName: offeringInstance?.offeringName,
            usageIncrement: parseInt(usageIncrement),
            dimensionUnit: unit,
            negative,
            tierName: tier?.tierName,
        });
        lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
    });
    return lineItems;
}

