import { plainToInstance } from 'class-transformer';
import { validateSync } from 'class-validator';
import {
    countBasedUnits,
    CreateDimensionDto,
    overageAllowedEnum,
    roundingEnum,
} from './create-dimension.dto.js';
import { UpdateDimensionDto } from './update-dimension.dto.js';
import { getSortedTiers, sortTiersByPosition, validateDimensionTiers } from './tierValidator.js';

const validTiers = [
    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.05' },
    { tierPosition: '2', upperBound: 'inf', tierName: 'Everything else', unitPrice: '0.03' },
];

const dimensionPayload = (overrides: Record<string, unknown> = {}) => ({
    dimensionName: 'Requests',
    consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
    usageIncrement: '1',
    rounding: roundingEnum.ceiling,
    ...overrides,
});

const errorsFor = (payload: Record<string, unknown>, dto = CreateDimensionDto) =>
    validateSync(plainToInstance(dto, payload) as object).map((error) => JSON.stringify(error.constraints));

describe('dimension pricing tiers validation', () => {
    describe('validateDimensionTiers', () => {
        it('should accept tiers which increase without overlapping and end with inf', () => {
            expect(validateDimensionTiers({ tiers: validTiers, usageIncrement: '1' })).toEqual([]);
        });
        it('should treat missing tiers as valid', () => {
            expect(validateDimensionTiers({ tiers: undefined, usageIncrement: '1' })).toEqual([]);
            expect(validateDimensionTiers({ tiers: null, usageIncrement: '1' })).toEqual([]);
        });
        it('should reject an empty tiers array', () => {
            expect(validateDimensionTiers({ tiers: [], usageIncrement: '1' })).toHaveLength(1);
        });
        it('should reject bounds which do not increase', () => {
            const errors = validateDimensionTiers({
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: '1000', unitPrice: '0.03' },
                ],
                usageIncrement: '1',
            });
            expect(errors).toHaveLength(1);
            expect(errors[0]).toContain('increase without overlapping');
        });
        it('should reject bounds which overlap after being sorted by tierPosition', () => {
            const errors = validateDimensionTiers({
                tiers: [
                    { tierPosition: '2', upperBound: '500', unitPrice: '0.03' },
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                ],
                usageIncrement: '1',
            });
            expect(errors).toHaveLength(1);
            expect(errors[0]).toContain('increase without overlapping');
        });
        it('should reject bounds which are not aligned to the usageIncrement', () => {
            const errors = validateDimensionTiers({
                tiers: [
                    { tierPosition: '1', upperBound: '1050', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                ],
                usageIncrement: '100',
            });
            expect(errors).toHaveLength(1);
            expect(errors[0]).toContain('must be a multiple of the usageIncrement');
        });
        it('should accept bounds which are aligned to the usageIncrement', () => {
            expect(
                validateDimensionTiers({
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                    ],
                    usageIncrement: '100',
                }),
            ).toEqual([]);
        });
        it('should only allow inf on the last tier', () => {
            const errors = validateDimensionTiers({
                tiers: [
                    { tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: '2000', unitPrice: '0.03' },
                ],
                usageIncrement: '1',
            });
            expect(errors.join('. ')).toContain('only the last tier can have an upperBound of "inf"');
        });
        it('should require a unitPrice on every tier after the first', () => {
            const errors = validateDimensionTiers({
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf' },
                ],
                usageIncrement: '1',
            });
            expect(errors).toHaveLength(1);
            expect(errors[0]).toContain('requires a unitPrice');
        });
        it('should allow the first tier to omit its unitPrice, representing a free tier', () => {
            expect(
                validateDimensionTiers({
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', tierName: 'Free' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                    ],
                    usageIncrement: '1',
                }),
            ).toEqual([]);
        });
        it('should reject unit prices with more than 8 decimal places', () => {
            const errors = validateDimensionTiers({
                tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.000000004' }],
                usageIncrement: '1',
            });
            expect(errors).toHaveLength(1);
            expect(errors[0]).toContain('digits of precision');
        });
        it('should reject non numeric bounds, positions and prices', () => {
            expect(
                validateDimensionTiers({
                    tiers: [{ tierPosition: 'first', upperBound: 'abc', unitPrice: 'free' }],
                    usageIncrement: '1',
                }),
            ).toHaveLength(3);
        });
        it('should reject duplicated tier positions', () => {
            const errors = validateDimensionTiers({
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '1', upperBound: 'inf', unitPrice: '0.03' },
                ],
                usageIncrement: '1',
            });
            expect(errors.join('. ')).toContain('unique tierPosition');
        });
        it('should be mutually exclusive with consumptionPrice, usageEntitlement and overage', () => {
            expect(
                validateDimensionTiers({ tiers: validTiers, usageIncrement: '1', consumptionPrice: '2' }).join('. '),
            ).toContain('consumptionPrice');
            expect(
                validateDimensionTiers({ tiers: validTiers, usageIncrement: '1', usageEntitlement: 100 }).join('. '),
            ).toContain('usageEntitlement');
            expect(
                validateDimensionTiers({
                    tiers: validTiers,
                    usageIncrement: '1',
                    overageAllowed: overageAllowedEnum.true,
                }).join('. '),
            ).toContain('overageAllowed');
            expect(
                validateDimensionTiers({
                    tiers: validTiers,
                    usageIncrement: '1',
                    overageAllowed: overageAllowedEnum.false,
                }),
            ).toEqual([]);
        });
    });

    describe('sorting helpers', () => {
        it('should sort tier positions numerically and not lexicographically', () => {
            const tiers = [
                { tierPosition: '10', upperBound: 'inf', unitPrice: '1' },
                { tierPosition: '2', upperBound: '20', unitPrice: '2' },
                { tierPosition: '1', upperBound: '10', unitPrice: '3' },
            ];
            expect(sortTiersByPosition(tiers).map(({ tierPosition }) => tierPosition)).toEqual(['1', '2', '10']);
            expect(getSortedTiers({ tiers }).map(({ tierPosition }) => tierPosition)).toEqual(['1', '2', '10']);
        });
        it('should return an empty array of tiers for dimensions which are not tiered', () => {
            expect(getSortedTiers(undefined)).toEqual([]);
            expect(getSortedTiers({ tiers: null })).toEqual([]);
            expect(getSortedTiers({ tiers: [] })).toEqual([]);
        });
    });

    describe('CreateDimensionDto', () => {
        it('should accept a tiered dimension which does not set a consumption price', () => {
            expect(errorsFor(dimensionPayload({ tiers: validTiers }))).toEqual([]);
        });
        it('should keep rejecting a dimension without a consumption price, tiers and entitlement', () => {
            expect(errorsFor(dimensionPayload()).join('. ')).toContain('Consumption price should be set');
        });
        it('should reject a tiered dimension which also sets a consumption price', () => {
            expect(errorsFor(dimensionPayload({ tiers: validTiers, consumptionPrice: '2' })).join('. ')).toContain(
                'consumptionPrice',
            );
        });
        it('should reject a tiered dimension which also sets a usage entitlement', () => {
            expect(errorsFor(dimensionPayload({ tiers: validTiers, usageEntitlement: 10 })).join('. ')).toContain(
                'usageEntitlement',
            );
        });
        it('should reject a tiered dimension with bounds which are not aligned to the usage increment', () => {
            expect(
                errorsFor(
                    dimensionPayload({
                        usageIncrement: '24',
                        tiers: [{ tierPosition: '1', upperBound: '100', unitPrice: '1' }],
                    }),
                ).join('. '),
            ).toContain('must be a multiple of the usageIncrement');
        });
        it('should reject tiers which are not an array', () => {
            expect(errorsFor(dimensionPayload({ tiers: 'foobar' }))).not.toEqual([]);
        });
        it('should allow clearing the tiers of a dimension with null on an update', () => {
            expect(errorsFor({ tiers: null }, UpdateDimensionDto)).toEqual([]);
        });
        it('should validate the tiers given to an update', () => {
            expect(
                errorsFor(
                    { tiers: [{ tierPosition: '1', upperBound: '10', unitPrice: '1' }, { tierPosition: '2' }] },
                    UpdateDimensionDto,
                ),
            ).not.toEqual([]);
        });
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { BadRequestException } from '@nestjs/common';
import { DimensionsService } from './dimensions.service.js';
import {
    countBasedUnits,
    CreateDimensionDto,
    DimensionTier,
    overageAllowedEnum,
    roundingEnum,
} from './dto/create-dimension.dto.js';
import { DimensionEntity, Numerical } from './entities/dimensions.entity.js';
import { ReadDimensionResponseData } from './dto/read-dimension.dto.js';

const tiers: DimensionTier[] = [
    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.05' },
    { tierPosition: '2', upperBound: 'inf', tierName: 'Everything else', unitPrice: '0.03' },
];

const tieredDimension = (overrides: Partial<CreateDimensionDto> = {}): CreateDimensionDto =>
    ({
        dimensionName: 'Requests',
        businessID: 'fakeBusinessID',
        consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
        usageIncrement: '1',
        rounding: roundingEnum.ceiling,
        tiers,
        ...overrides,
    }) as CreateDimensionDto;

describe('DimensionsService pricing tiers', () => {
    let service: DimensionsService;

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [DimensionsService],
        })
            .useMocker(createMock)
            .compile();

        service = module.get<DimensionsService>(DimensionsService);
    });

    describe('persistence', () => {
        it('should keep the tiers on the entity input of a dimension', () => {
            const input = service.transformDtoToEntityInput(tieredDimension(), 'fakeDimensionId');
            expect(input.numerical.tiers).toEqual(tiers);
        });
        it('should not set any tiers on a dimension which is not tiered', () => {
            const input = service.transformDtoToEntityInput(
                tieredDimension({ tiers: undefined, consumptionPrice: '2' }),
                'fakeDimensionId',
            );
            expect(input.numerical.tiers).toBeUndefined();
            expect(input.numerical.priceSegments[0].price).toEqual('2');
        });
        it('should return the same tiers after a round trip through the ledger', () => {
            const input = service.transformDtoToEntityInput(tieredDimension(), 'fakeDimensionId');
            const row: Record<string, unknown> = { _value: 'Requests' };
            const fakePoint = {
                tag: (key: string, value: string) => {
                    row[key] = value;
                    return fakePoint;
                },
            };
            //eslint-disable-next-line
            //@ts-ignore the point is faked so the tags written to the ledger can be inspected
            Numerical.transformer(input.numerical, fakePoint);
            expect(row.tiers).toEqual(JSON.stringify(tiers));

            const entity = DimensionEntity.dbModelToEntity({
                ...row,
                typeofDimension: 'numerical',
                dimensionId: 'fakeDimensionId',
                businessID: 'fakeBusinessID',
            });
            expect(entity.numerical.tiers).toEqual(tiers);
            expect(new CreateDimensionDto(entity).tiers).toEqual(tiers);
        });
        it('should not set tiers on the read model of a dimension without tiers', () => {
            const input = service.transformDtoToEntityInput(
                tieredDimension({ tiers: undefined, consumptionPrice: '2' }),
                'fakeDimensionId',
            );
            const row: Record<string, unknown> = { _value: 'Requests' };
            const fakePoint = {
                tag: (key: string, value: string) => {
                    row[key] = value;
                    return fakePoint;
                },
            };
            //eslint-disable-next-line
            //@ts-ignore the point is faked so the tags written to the ledger can be inspected
            Numerical.transformer(input.numerical, fakePoint);
            expect(row.tiers).toBeUndefined();
            const entity = DimensionEntity.dbModelToEntity({
                ...row,
                typeofDimension: 'numerical',
                dimensionId: 'fakeDimensionId',
                businessID: 'fakeBusinessID',
            });
            expect(entity.numerical.tiers).toBeUndefined();
            expect(new CreateDimensionDto(entity).tiers).toBeUndefined();
        });
    });

    describe('create', () => {
        it('should reject a dimension with invalid tiers', async () => {
            await expect(
                service.create(
                    tieredDimension({
                        tiers: [
                            { tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' },
                            { tierPosition: '2', upperBound: '2000', unitPrice: '0.03' },
                        ],
                    }),
                    'fakeSubject',
                ),
            ).rejects.toThrow(BadRequestException);
        });
        it('should persist a dimension with valid tiers', async () => {
            const transformSpy = jest.spyOn(service, 'transformDtoToEntityInput');
            const { dimensionId } = await service.create(tieredDimension(), 'fakeSubject');
            expect(dimensionId).toEqual(expect.any(String));
            expect(transformSpy).toHaveBeenCalledWith(expect.objectContaining({ tiers }), dimensionId);
        });
    });

    describe('update', () => {
        const storedTieredDimension = {
            dimensionId: 'fakeDimensionId',
            dimensionName: 'Requests',
            consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
            usageIncrement: '1',
            rounding: roundingEnum.ceiling,
            overageAllowed: overageAllowedEnum.false,
            tiers,
        } as unknown as ReadDimensionResponseData;
        const storedPricedDimension = {
            dimensionId: 'fakeDimensionId',
            dimensionName: 'Requests',
            consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
            usageIncrement: '1',
            rounding: roundingEnum.ceiling,
            overageAllowed: overageAllowedEnum.false,
            consumptionPrice: '2',
        } as unknown as ReadDimensionResponseData;

        it('should keep the stored tiers when the update does not mention them', () => {
            expect(
                service.mergeTiersForUpdate({ storedDimension: storedTieredDimension, updatedFields: {} }).tiers,
            ).toEqual(tiers);
        });
        it('should replace the stored tiers with the tiers of the update', () => {
            const replacementTiers = [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.09' }];
            expect(
                service.mergeTiersForUpdate({
                    storedDimension: storedTieredDimension,
                    updatedFields: { tiers: replacementTiers },
                }).tiers,
            ).toEqual(replacementTiers);
        });
        it('should clear the tiers of a dimension when null is passed', () => {
            expect(
                service.mergeTiersForUpdate({
                    storedDimension: storedTieredDimension,
                    updatedFields: { tiers: null },
                }),
            ).toEqual({ tiers: undefined });
        });
        it('should remove the mutually exclusive pricing fields of a dimension which becomes tiered', () => {
            expect(
                service.mergeTiersForUpdate({ storedDimension: storedPricedDimension, updatedFields: { tiers } }),
            ).toEqual({
                tiers,
                consumptionPrice: undefined,
                usageEntitlement: undefined,
                overageAllowed: overageAllowedEnum.false,
            });
        });
        it('should reject an update which sets tiers together with a consumption price', () => {
            expect(() =>
                service.mergeTiersForUpdate({
                    storedDimension: storedPricedDimension,
                    updatedFields: { tiers, consumptionPrice: '2' },
                }),
            ).toThrow(BadRequestException);
        });
        it('should reject an update which sets tiers together with an entitlement or overage', () => {
            expect(() =>
                service.mergeTiersForUpdate({
                    storedDimension: storedPricedDimension,
                    updatedFields: { tiers, usageEntitlement: 100 },
                }),
            ).toThrow(BadRequestException);
            expect(() =>
                service.mergeTiersForUpdate({
                    storedDimension: storedPricedDimension,
                    updatedFields: { tiers, overageAllowed: overageAllowedEnum.true },
                }),
            ).toThrow(BadRequestException);
        });
        it('should validate the tiers against the usage increment of the update', () => {
            expect(() =>
                service.mergeTiersForUpdate({
                    storedDimension: storedTieredDimension,
                    updatedFields: { usageIncrement: '24' },
                }),
            ).toThrow(BadRequestException);
        });
        it('should replace the tiers of a stored dimension through the update flow', async () => {
            jest.spyOn(service, 'findOne').mockResolvedValue({
                data: [{ ...storedPricedDimension }],
                message: 'Found Dimension',
            });
            const transformSpy = jest.spyOn(service, 'transformDtoToEntityInput');
            await service.update({ dimensionId: 'fakeDimensionId', businessID: 'fakeBusinessID', tiers }, 'subject');
            expect(transformSpy).toHaveBeenCalledWith(
                expect.objectContaining({ tiers, consumptionPrice: undefined }),
                'fakeDimensionId',
            );
        });
        it('should clear the tiers of a stored dimension through the update flow', async () => {
            jest.spyOn(service, 'findOne').mockResolvedValue({
                data: [{ ...storedTieredDimension }],
                message: 'Found Dimension',
            });
            const transformSpy = jest.spyOn(service, 'transformDtoToEntityInput');
            await service.update(
                { dimensionId: 'fakeDimensionId', businessID: 'fakeBusinessID', tiers: null },
                'subject',
            );
            expect(transformSpy).toHaveBeenCalledWith(
                expect.objectContaining({ tiers: undefined }),
                'fakeDimensionId',
            );
        });
    });
});

import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    DimensionTier,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { ReadDimensionResponseData } from '../../dimensions/dto/read-dimension.dto.js';
import { InvoiceLineItem, InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { DatetimeUtils } from '../../utils/datetime.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Billing } from '../../billing/entities/billing.entity.js';
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 0.91),
    },
}));

const fakeBusinessID = 'fakeBusinessID';
const fakeCustomerID = 'fakeCustomerID';
const dimensionId = '123';

const twoTiers: DimensionTier[] = [
    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.1' },
    { tierPosition: '2', upperBound: 'inf', tierName: 'Above 1000', unitPrice: '0.05' },
];

describe('Volume based pricing tiers billing', () => {
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;
    let settings: ReadSettingsResponseData;
    let customer: ReadCustomerResponseData;

    const usageOffering = (dimensions: ReadDimensionResponseData[]): ReadOfferingResponseData => ({
        offeringId: '123',
        offeringName: 'foobar',
        offeringType: OfferingType.usageBased,
        currency: SupportedCurrencies.USD,
        billingCycle: ValidBillingCycles.monthly,
        dimensions,
    });

    const tieredDimension = (overrides: Partial<ReadDimensionResponseData> = {}): ReadDimensionResponseData =>
        ({
            dimensionId,
            dimensionName: 'Requests',
            aggregationInterval: aggregationInterval.day,
            aggregationMethod: aggregationMethod.sum,
            usageIncrement: '1',
            consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
            rounding: roundingEnum.ceiling,
            tiers: twoTiers,
            ...overrides,
        }) as ReadDimensionResponseData;

    const mockUsage = (value: string) => {
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId,
                            usage: [
                                {
                                    startTime: DatetimeUtils.beginningOfDay(new Date()).toISOString(),
                                    endTime: DatetimeUtils.endOfDay(new Date()).toISOString(),
                                    value,
                                },
                            ],
                        },
                    ],
                }) as ReadCustomerUsageData,
        );
    };

    const getLineItems = async ({
        dimensions,
        customerOverride,
    }: {
        dimensions: ReadDimensionResponseData[];
        customerOverride?: ReadCustomerResponseData;
    }) => {
        const offeringInstance = Offering.getInstance(
            usageOffering(dimensions),
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            settings,
            schedulerService,
            customerService,
        );
        const lineItems = await Offering.getLineItemsForUsage({
            customerService,
            customer: customerOverride ?? customer,
            startDate: DatetimeUtils.beginningOfDay(new Date()),
            endDate: DatetimeUtils.endOfDay(new Date()),
            customerId: fakeCustomerID,
            businessID: fakeBusinessID,
            dimensions,
            lineItems: new InvoiceLineItems(),
            offeringInstance,
        });
        return lineItems.getLineItems();
    };

    beforeEach(() => {
        jest.useFakeTimers('modern').setSystemTime(new Date('2023-08-16'));
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'create').mockImplementation(async () => ({ invoiceId: '123', message: 'fake' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({}));
        settings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
        customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            currency: SupportedCurrencies.USD,
            email: 'fakeEmail',
        } as ReadCustomerResponseData;
    });

    afterEach(() => {
        jest.clearAllMocks();
        jest.useRealTimers();
    });

    describe('allocateUsageAcrossTiers', () => {
        it('should allocate usage across the inclusive bounds of the tiers', () => {
            expect(Billing.allocateUsageAcrossTiers({ totalUsage: 1500, tiers: twoTiers })).toEqual([
                { tier: twoTiers[0], usage: 1000 },
                { tier: twoTiers[1], usage: 500 },
            ]);
        });
        it('should only return the tiers which have been consumed', () => {
            expect(Billing.allocateUsageAcrossTiers({ totalUsage: 1000, tiers: twoTiers })).toEqual([
                { tier: twoTiers[0], usage: 1000 },
            ]);
            expect(Billing.allocateUsageAcrossTiers({ totalUsage: 0, tiers: twoTiers })).toEqual([]);
        });
        it('should sort the tiers by their numeric position before allocating usage', () => {
            const unsortedTiers = [
                { tierPosition: '10', upperBound: 'inf', unitPrice: '0.01' },
                { tierPosition: '2', upperBound: '200', unitPrice: '0.05' },
                { tierPosition: '1', upperBound: '100', unitPrice: '0.1' },
            ];
            expect(Billing.allocateUsageAcrossTiers({ totalUsage: 250, tiers: unsortedTiers })).toEqual([
                { tier: unsortedTiers[2], usage: 100 },
                { tier: unsortedTiers[1], usage: 100 },
                { tier: unsortedTiers[0], usage: 50 },
            ]);
        });
    });

    describe('line items', () => {
        it('should create a line item for every consumed tier', async () => {
            mockUsage('1500');
            expect(await getLineItems({ dimensions: [tieredDimension()] })).toEqual([
                new InvoiceLineItem('Requests - foobar - First 1000', 1000, 0.1),
                new InvoiceLineItem('Requests - foobar - Above 1000', 500, 0.05),
            ]);
        });
        it('should not create a line item for a tier which has not been consumed', async () => {
            mockUsage('400');
            expect(await getLineItems({ dimensions: [tieredDimension()] })).toEqual([
                new InvoiceLineItem('Requests - foobar - First 1000', 400, 0.1),
            ]);
        });
        it('should not append a tier name when the tier does not have one', async () => {
            mockUsage('1500');
            const lineItems = await getLineItems({
                dimensions: [
                    tieredDimension({
                        tiers: [
                            { tierPosition: '1', upperBound: '1000', unitPrice: '0.1' },
                            { tierPosition: '2', upperBound: 'inf', unitPrice: '0.05' },
                        ],
                    }),
                ],
            });
            expect(lineItems).toEqual([
                new InvoiceLineItem('Requests - foobar', 1000, 0.1),
                new InvoiceLineItem('Requests - foobar', 500, 0.05),
            ]);
        });
        it('should divide the quantity of every tier by the usage increment', async () => {
            mockUsage('1500');
            expect(
                await getLineItems({
                    dimensions: [
                        tieredDimension({
                            usageIncrement: '100',
                            tiers: [
                                { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.1' },
                                { tierPosition: '2', upperBound: 'inf', tierName: 'Above 1000', unitPrice: '0.05' },
                            ],
                        }),
                    ],
                }),
            ).toEqual([
                new InvoiceLineItem('Requests - foobar - First 1000', 10, 0.1),
                new InvoiceLineItem('Requests - foobar - Above 1000', 5, 0.05),
            ]);
        });
        it('should bill a first tier without a unit price as a free tier', async () => {
            mockUsage('1500');
            expect(
                await getLineItems({
                    dimensions: [
                        tieredDimension({
                            tiers: [
                                { tierPosition: '1', upperBound: '1000', tierName: 'Free' },
                                { tierPosition: '2', upperBound: 'inf', tierName: 'Paid', unitPrice: '0.05' },
                            ],
                        }),
                    ],
                }),
            ).toEqual([
                new InvoiceLineItem('Requests - foobar - Free', 1000, 0),
                new InvoiceLineItem('Requests - foobar - Paid', 500, 0.05),
            ]);
        });
        it('should hide a free tier when free dimensions are hidden on the invoice', async () => {
            settings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.hide } as ReadSettingsResponseData;
            mockUsage('1500');
            expect(
                await getLineItems({
                    dimensions: [
                        tieredDimension({
                            tiers: [
                                { tierPosition: '1', upperBound: '1000', tierName: 'Free' },
                                { tierPosition: '2', upperBound: 'inf', tierName: 'Paid', unitPrice: '0.05' },
                            ],
                        }),
                    ],
                }),
            ).toEqual([new InvoiceLineItem('Requests - foobar - Paid', 500, 0.05)]);
        });
        it('should preserve the precision of the unit price of every tier', async () => {
            mockUsage('1500');
            expect(
                await getLineItems({
                    dimensions: [
                        tieredDimension({
                            tiers: [
                                { tierPosition: '1', upperBound: '1000', unitPrice: '1.23456789' },
                                { tierPosition: '2', upperBound: 'inf', unitPrice: '0.00000001' },
                            ],
                        }),
                    ],
                }),
            ).toEqual([
                new InvoiceLineItem('Requests - foobar', 1000, 1.23456789),
                new InvoiceLineItem('Requests - foobar', 500, 0.00000001),
            ]);
        });
        it('should convert the unit price of every tier into the currency of the customer', async () => {
            mockUsage('1500');
            expect(
                await getLineItems({
                    dimensions: [tieredDimension()],
                    customerOverride: { ...customer, currency: SupportedCurrencies.EUR },
                }),
            ).toEqual([
                // 0.91 is the exchange rate returned by the mocked analytics service
                new InvoiceLineItem('Requests - foobar - First 1000', 1000, 0.09),
                new InvoiceLineItem('Requests - foobar - Above 1000', 500, 0.05),
            ]);
        });
        it('should keep charging non tiered dimensions in the same way', async () => {
            mockUsage('1500');
            expect(
                await getLineItems({
                    dimensions: [tieredDimension({ tiers: undefined, consumptionPrice: '0.1' })],
                }),
            ).toEqual([new InvoiceLineItem('Requests - foobar', 1500, 0.1)]);
        });
        it('should not charge for a dimension without tiers, consumption price and entitlement', async () => {
            mockUsage('1500');
            expect(await getLineItems({ dimensions: [tieredDimension({ tiers: undefined })] })).toEqual([]);
        });
        it('should not charge for a dimension whose tiers have been cleared', async () => {
            mockUsage('1500');
            expect(await getLineItems({ dimensions: [tieredDimension({ tiers: null })] })).toEqual([]);
        });
        it('should create the tier line items of an invoice through the billing process', async () => {
            mockUsage('1500');
            const offeringInstance = Offering.getInstance(
                usageOffering([tieredDimension()]),
                fakeCustomerID,
                fakeBusinessID,
                invoicesService,
                settings,
                schedulerService,
                customerService,
            );
            await offeringInstance.processBilling(undefined, undefined, customer);
            expect(invoicesService.create).toHaveBeenCalledWith(
                expect.objectContaining({
                    items: {
                        lineItems: [
                            { name: 'Requests - foobar - First 1000', quantity: 1000, unitCost: 0.1 },
                            { name: 'Requests - foobar - Above 1000', quantity: 500, unitCost: 0.05 },
                        ],
                    },
                }),
            );
        });
    });
});

